package io.github.jesterportfolio.hearth.persistence;
import java.util.*;import java.util.concurrent.*;import java.sql.*;import javax.sql.DataSource;
import io.github.jesterportfolio.hearth.economy.*;import io.github.jesterportfolio.hearth.inventory.*;
public final class EnchantDatabaseChecks {
 static <T>T await(CompletionStage<T> stage)throws Exception{return stage.toCompletableFuture().get(12,TimeUnit.SECONDS);}
 static void check(boolean b,String name){if(!b)throw new IllegalStateException(name);System.out.println("HEARTH_ENCHANT_DB_CHECK PASS "+name);System.out.flush();}
 static void reject(CompletionStage<?> stage)throws Exception{try{await(stage);throw new IllegalStateException("EXPECTED_REJECTION");}catch(ExecutionException expected){}}
 public static void run(DataSource source,Connection connection)throws Exception{
  var p=new Properties();try(var in=EnchantDatabaseChecks.class.getResourceAsStream("/economy-demo.properties")){p.load(in);}p.setProperty("fixture-balance","0");var db=PostgresProgressStore.forModules(source,f->{});var economy=new EconomyStore(db,EconomyContent.parse(p));await(economy.migrate());await(economy.migrate());var store=new EnchantStore(db,economy);var realm=UUID.randomUUID();await(economy.openNativeRealm(realm,UUID.randomUUID(),"a".repeat(64),1,true));var actor=economy.context(realm,UUID.randomUUID());var other=economy.context(realm,UUID.randomUUID());var before=InventoryPayload.pack(new byte[41][]);var slots=new byte[41][];slots[0]=new byte[]{3,4,5};var after=InventoryPayload.pack(slots);await(economy.ensureAccount(actor,before));await(economy.ensureAccount(other,before));try(var s=connection.prepareStatement("UPDATE hearth_economy.account SET balance=100 WHERE realm_id=? AND player_uuid=?")){s.setObject(1,realm);s.setObject(2,actor.playerId());s.executeUpdate();}
  check(true,"E011_upgrade_is_idempotent_and_existing_migration_checksums_match");
  UUID id=UUID.randomUUID();var intent=new EnchantStore.Intent(id,"fixed-success-roll-.1","FUSE","hearth:ce_haste",before,after,"SUCCESS",.5,.1,7,0);var a=store.execute(actor,intent,()->true);var b=store.execute(actor,intent,()->true);var ra=await(a);var rb=await(b);check(ra.replay()!=rb.replay()&&await(economy.account(actor)).balance()==93&&await(economy.account(actor)).inventory().revision()==1,"concurrent_same_request_pays_and_applies_PG_shadow_once");check((ra.replay()?rb:ra).after().equals(after)&&(ra.replay()?ra:rb).after()==null,"replay_has_no_inventory_payload_for_automatic_regrant");reject(store.execute(other,intent,()->true));reject(store.execute(actor,new EnchantStore.Intent(id,"changed-roll","FUSE","hearth:ce_haste",before,after,"FAIL",.5,.9,7,0),()->true));check(await(economy.account(actor)).balance()==93,"request_owner_and_roll_fingerprint_are_immutable");
  reject(store.execute(new ServerProgressAccess().forVerifiedServerLink(realm,actor.playerId()),intent,()->true));check(true,"foreign_context_issuer_is_denied");
  check(await(store.inspect(actor,id)).orElseThrow().contains("outcome=SUCCESS")&&await(store.inspect(other,id)).isEmpty(),"pending_inspection_is_read_only_owner_scoped_and_includes_fixed_roll");
  var stale=new EnchantStore.Intent(UUID.randomUUID(),"stale","EXTRACT","hearth:ce_haste",after,before,"FAIL",0,.5,1,0);reject(store.execute(actor,stale,()->true));check(await(economy.account(actor)).inventory().payload().equals(after),"stale_revision_never_replaces_original_native_shadow");
  var revoked=new EnchantStore.Intent(UUID.randomUUID(),"revoked","APPLY","hearth:ce_haste",after,before,"SUCCESS",1,.1,5,1);reject(store.execute(actor,revoked,()->false));check(await(economy.account(actor)).balance()==93,"revoked_native_session_does_not_charge_or_write_receipt");
  try(var s=connection.createStatement()){s.execute("CREATE FUNCTION hearth_economy.reject_enchant_fixture() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'enchant fixture failure' USING ERRCODE='23514'; END $$");s.execute("CREATE TRIGGER reject_enchant_fixture BEFORE INSERT ON hearth_economy.enchant_operation FOR EACH ROW EXECUTE FUNCTION hearth_economy.reject_enchant_fixture()");}reject(store.execute(actor,revoked,()->true));check(await(economy.account(actor)).balance()==93&&await(economy.account(actor)).inventory().payload().equals(after),"receipt_SQL_failure_rolls_back_wallet_and_material_shadow");try(var s=connection.createStatement()){s.execute("DROP TRIGGER reject_enchant_fixture ON hearth_economy.enchant_operation");s.execute("DROP FUNCTION hearth_economy.reject_enchant_fixture()");}
  var fail=new EnchantStore.Intent(UUID.randomUUID(),"fixed-fail-roll-.9","EXTRACT","hearth:ce_haste",after,before,"FAIL",.2,.9,3,1);var loss=await(store.execute(actor,fail,()->true));check(loss.outcome().equals("FAIL")&&await(economy.account(actor)).balance()==90&&await(economy.account(actor)).inventory().payload().equals(before),"failed_extraction_outcome_and_cost_are_committed_once");
  await(store.saveCooldowns(realm,Map.of(actor.playerId(),Map.of("hearth:ce_tamer",3000L))));await(store.saveCooldowns(realm,Map.of(actor.playerId(),Map.of("hearth:ce_tamer",2000L))));check(await(store.cooldowns(realm,0)).get(actor.playerId()).get("hearth:ce_tamer")==3000,"coalesced_cooldown_save_never_shortens_deadline");check(await(store.history(actor)).size()==2,"history_is_actor_scoped_and_records_success_and_failure");
  String checksum;try(var s=connection.createStatement();var r=s.executeQuery("SELECT checksum FROM hearth_economy.version WHERE version=11")){r.next();checksum=r.getString(1);}try(var s=connection.createStatement()){s.execute("UPDATE hearth_economy.version SET checksum='enchant-fixture-mismatch' WHERE version=11");}var mismatch=PostgresProgressStore.forModules(source,f->{});reject(new EconomyStore(mismatch,EconomyContent.parse(p)).migrate());await(mismatch.closeAsync());try(var s=connection.prepareStatement("UPDATE hearth_economy.version SET checksum=? WHERE version=11")){s.setString(1,checksum);s.executeUpdate();}check(await(economy.account(actor)).balance()==90,"E011_checksum_mismatch_keeps_inventory_money_and_receipts");await(db.closeAsync());
 }
}
